package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

// ChatService runs replies for the chat UI. A reply is generated by the
// server, not the browser: it keeps going (and is saved as it streams) when
// the tab closes or a phone locks, and any open tab can follow it live.
type ChatService struct {
	store *ChatStore
	mgr   *Manager
	// reader describes images for models that can't see; nil when
	// image_recognition is off.
	reader *imageReader
	// images makes pictures for chats that picked image-gen; nil when
	// image_generation is off.
	images *imageGen

	ctx    context.Context
	cancel context.CancelFunc
	wg     sync.WaitGroup

	mu   sync.Mutex
	gens map[string]*generation // by chat ID
}

// saveEvery bounds how much of a streaming reply a crash can lose.
var saveEvery = 750 * time.Millisecond

func NewChatService(store *ChatStore, mgr *Manager) *ChatService {
	ctx, cancel := context.WithCancel(context.Background())
	return &ChatService{store: store, mgr: mgr, ctx: ctx, cancel: cancel, gens: map[string]*generation{}}
}

// Shutdown stops every reply and waits for the final saves.
func (cs *ChatService) Shutdown(timeout time.Duration) {
	cs.cancel()
	done := make(chan struct{})
	go func() { cs.wg.Wait(); close(done) }()
	select {
	case <-done:
	case <-time.After(timeout):
		log.Printf("chat: replies did not stop within %v", timeout)
	}
}

type genEvent struct {
	Type string
	Data any
}

type genSnapshot struct {
	MessageID string `json:"message_id"`
	VariantID string `json:"variant_id"`
	Content   string `json:"content"`
	Reasoning string `json:"reasoning"`
	Done      bool   `json:"done"`
	// Status says what the reply waits on before the model starts, like
	// the image reader, or how far an image is.
	Status string `json:"status,omitempty"`
	// Preview is a rough look at an image while it forms, as a data URL.
	Preview string `json:"preview,omitempty"`
}

type genDone struct {
	MessageID   string           `json:"message_id"`
	VariantID   string           `json:"variant_id"`
	Status      string           `json:"status"`
	Error       string           `json:"error,omitempty"`
	Content     string           `json:"content"`
	Reasoning   string           `json:"reasoning,omitempty"`
	ReasoningMs int64            `json:"reasoning_ms,omitempty"`
	Stats       json.RawMessage  `json:"stats,omitempty"`
	Images      []AttachmentMeta `json:"images,omitempty"`
}

type generation struct {
	t      turn
	cancel context.CancelFunc

	mu        sync.Mutex
	content   strings.Builder
	reasoning strings.Builder
	finished  bool
	final     genDone
	status    string
	preview   string
	subs      map[chan genEvent]struct{}
}

func (g *generation) setStatus(s string) {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.status = s
	g.publish(genEvent{"status", map[string]string{"text": s}})
}

// setPreview shows how far an image is, with a rough look at it.
func (g *generation) setPreview(status, dataURL string) {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.status, g.preview = status, dataURL
	g.publish(genEvent{"status", map[string]string{"text": status, "preview": dataURL}})
}

func (g *generation) publish(ev genEvent) {
	for ch := range g.subs {
		select {
		case ch <- ev:
		default:
			// A subscriber that can't keep up is dropped; its browser
			// reconnects and resyncs from a fresh snapshot.
			delete(g.subs, ch)
			close(ch)
		}
	}
}

func (g *generation) closeSubs() {
	for ch := range g.subs {
		delete(g.subs, ch)
		close(ch)
	}
}

// Active reports whether a reply is streaming in the chat.
func (cs *ChatService) Active(chatID string) bool {
	cs.mu.Lock()
	defer cs.mu.Unlock()
	g := cs.gens[chatID]
	if g == nil {
		return false
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	return !g.finished
}

// Subscribe follows the chat's reply. ok is false when nothing is running.
func (cs *ChatService) Subscribe(chatID string) (snap genSnapshot, ch chan genEvent, unsubscribe func(), ok bool) {
	cs.mu.Lock()
	g := cs.gens[chatID]
	cs.mu.Unlock()
	if g == nil {
		return snap, nil, nil, false
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	snap = genSnapshot{MessageID: g.t.MessageID, VariantID: g.t.VariantID, Content: g.content.String(), Reasoning: g.reasoning.String(), Done: g.finished, Status: g.status, Preview: g.preview}
	ch = make(chan genEvent, 512)
	if g.finished {
		ch <- genEvent{"done", g.final}
	}
	g.subs[ch] = struct{}{}
	return snap, ch, func() {
		g.mu.Lock()
		defer g.mu.Unlock()
		if _, live := g.subs[ch]; live {
			delete(g.subs, ch)
			close(ch)
		}
	}, true
}

// Stop ends the chat's reply, keeping what was written so far.
func (cs *ChatService) Stop(chatID string) bool {
	cs.mu.Lock()
	g := cs.gens[chatID]
	cs.mu.Unlock()
	if g == nil {
		return false
	}
	g.cancel()
	return true
}

var errChatBusy = errors.New("a reply is still being written in this chat; stop it first")

// claim reserves the chat for a new reply. A finished generation that is
// only waiting on its title doesn't block the next message.
func (cs *ChatService) claim(chatID string) error {
	cs.mu.Lock()
	defer cs.mu.Unlock()
	if g, exists := cs.gens[chatID]; exists {
		if g == nil { // another request is between claim and start
			return errChatBusy
		}
		g.mu.Lock()
		finished := g.finished
		g.mu.Unlock()
		if !finished {
			return errChatBusy
		}
	}
	cs.gens[chatID] = nil // placeholder until start
	return nil
}

func (cs *ChatService) release(chatID string) {
	cs.mu.Lock()
	defer cs.mu.Unlock()
	if g, ok := cs.gens[chatID]; ok && g == nil {
		delete(cs.gens, chatID)
	}
}

// runningInstance resolves the chat's instance, which must be serving.
func (cs *ChatService) runningInstance(name string) (*Instance, error) {
	inst := cs.mgr.Get(name)
	if inst == nil {
		return nil, fmt.Errorf("instance %q doesn't exist anymore; pick another one", name)
	}
	if s := inst.State(); s != StateRunning {
		return nil, fmt.Errorf("%s is %s; start it to get a reply", name, s)
	}
	return inst, nil
}

// start runs the reply for t in the background.
func (cs *ChatService) start(t turn, inst *Instance, params chatParams) {
	ctx, cancel := context.WithCancel(cs.ctx)
	g := &generation{t: t, cancel: cancel, subs: map[chan genEvent]struct{}{}}
	cs.mu.Lock()
	if old := cs.gens[t.ChatID]; old != nil {
		old.mu.Lock()
		old.closeSubs()
		old.mu.Unlock()
	}
	cs.gens[t.ChatID] = g
	cs.mu.Unlock()

	cs.wg.Add(1)
	go func() {
		defer cs.wg.Done()
		defer cancel()
		final := cs.generate(ctx, g, inst, params)
		g.mu.Lock()
		g.finished, g.final = true, final
		g.publish(genEvent{"done", final})
		g.mu.Unlock()

		if t.Seq == 1 && final.Status == variantDone && inst.conf.role != roleImageGen {
			if title := cs.writeTitle(inst, t.ChatID); title != "" {
				g.mu.Lock()
				g.publish(genEvent{"title", map[string]string{"title": title}})
				g.mu.Unlock()
			}
		}
		cs.mu.Lock()
		if cs.gens[t.ChatID] == g {
			delete(cs.gens, t.ChatID)
		}
		cs.mu.Unlock()
		g.mu.Lock()
		g.closeSubs()
		g.mu.Unlock()
	}()
}

// chatParams is the subset of a chat's saved settings sent to llama-server.
// The UI stores them loosely (an empty field is ""), so each is optional.
type chatParams struct {
	System string
	Think  bool
	Size   string // WxH, for image-gen
	opts   map[string]any
}

func parseChatParams(raw json.RawMessage) chatParams {
	p := chatParams{Think: true, opts: map[string]any{}}
	var m map[string]any
	if json.Unmarshal(raw, &m) != nil {
		return p
	}
	num := func(k string) (float64, bool) {
		switch v := m[k].(type) {
		case float64:
			return v, true
		case string:
			f, err := strconv.ParseFloat(strings.TrimSpace(v), 64)
			return f, err == nil
		}
		return 0, false
	}
	if s, ok := m["sys"].(string); ok {
		p.System = strings.TrimSpace(s)
	}
	if b, ok := m["think"].(bool); ok {
		p.Think = b
	}
	if s, ok := m["size"].(string); ok {
		p.Size = s
	}
	for key, opt := range map[string]string{"temp": "temperature", "top_p": "top_p", "min_p": "min_p", "rep": "repeat_penalty"} {
		if v, ok := num(key); ok && v >= 0 {
			p.opts[opt] = v
		}
	}
	if v, ok := num("top_k"); ok && v >= 0 {
		p.opts["top_k"] = int(v)
	}
	if v, ok := num("max"); ok && v > 0 {
		p.opts["max_tokens"] = int(v)
	}
	if v, ok := num("seed"); ok {
		p.opts["seed"] = int64(v)
	}
	return p
}

type contentPart struct {
	Type     string            `json:"type"`
	Text     string            `json:"text,omitempty"`
	ImageURL map[string]string `json:"image_url,omitempty"`
}

// promptMessages turns stored history into OpenAI chat messages. Text files
// are inlined before the user's words. Images become image_url parts, which
// llama-server accepts when the model has a vision projector; a model that
// can't see (vision false) gets the image reader's description instead, when
// there is one.
func promptMessages(hist []historyTurn, system string, vision bool) []map[string]any {
	var msgs []map[string]any
	if system != "" {
		msgs = append(msgs, map[string]any{"role": "system", "content": system})
	}
	for _, h := range hist {
		// Files go before the question: models answer long documents better
		// when the question comes last.
		var files []string
		var images []contentPart
		for _, a := range h.Attachments {
			switch a.Kind {
			case "file":
				if a.isDoc() {
					files = append(files, fmt.Sprintf("Attached file %s (text extracted from the document):\n%s", a.Name, fence(a.Text)))
				} else {
					files = append(files, fmt.Sprintf("Attached file %s:\n%s", a.Name, fence(string(a.Data))))
				}
			case "image":
				if !vision && a.Text != "" {
					files = append(files, fmt.Sprintf("Attached image %s, described by an image-reading model because you can't see images (the description may contain mistakes):\n%s", a.Name, fence(a.Text)))
					continue
				}
				images = append(images, contentPart{Type: "image_url", ImageURL: map[string]string{
					"url": "data:" + a.Mime + ";base64," + base64.StdEncoding.EncodeToString(a.Data)}})
			}
		}
		text := h.Content
		if len(files) > 0 {
			text = strings.TrimSpace(strings.Join(files, "\n\n") + "\n\n" + h.Content)
		}
		if len(images) == 0 {
			msgs = append(msgs, map[string]any{"role": h.Role, "content": text})
			continue
		}
		parts := append([]contentPart{{Type: "text", Text: text}}, images...)
		msgs = append(msgs, map[string]any{"role": h.Role, "content": parts})
	}
	return msgs
}

type streamChunk struct {
	Choices []struct {
		Delta struct {
			Content          string `json:"content"`
			ReasoningContent string `json:"reasoning_content"`
		} `json:"delta"`
		FinishReason string `json:"finish_reason"`
	} `json:"choices"`
	Timings *struct {
		PromptN         int     `json:"prompt_n"`
		PromptPerSecond float64 `json:"prompt_per_second"`
		PredictedN      int     `json:"predicted_n"`
		PredictedPerSec float64 `json:"predicted_per_second"`
	} `json:"timings"`
	Usage *struct {
		CompletionTokens int `json:"completion_tokens"`
		PromptTokens     int `json:"prompt_tokens"`
	} `json:"usage"`
	Error *struct {
		Message string `json:"message"`
	} `json:"error"`
}

type replyStats struct {
	TPS       float64 `json:"tps,omitempty"`
	Tokens    int     `json:"tok,omitempty"`
	TTFTMs    int64   `json:"ttft,omitempty"`
	PromptTok int     `json:"prompt_tok,omitempty"`
	PromptTPS float64 `json:"prompt_tps,omitempty"`
	TotalMs   int64   `json:"total_ms"`
	Finish    string  `json:"finish,omitempty"`
}

// thinkSplitter routes text between <think> and </think> to the reasoning
// side, for servers that leave reasoning inline instead of in
// reasoning_content.
type thinkSplitter struct {
	pending string
	state   int // 0 undecided, 1 inside <think>, 2 plain
}

func (s *thinkSplitter) feed(chunk string) (content, reasoning string) {
	s.pending += chunk
	for {
		switch s.state {
		case 0:
			trimmed := strings.TrimLeft(s.pending, " \t\r\n")
			if strings.HasPrefix(trimmed, "<think>") {
				s.pending = strings.TrimPrefix(trimmed, "<think>")
				s.state = 1
				continue
			}
			if len(trimmed) < len("<think>") && strings.HasPrefix("<think>", trimmed) {
				return "", ""
			}
			s.state = 2
		case 1:
			if i := strings.Index(s.pending, "</think>"); i >= 0 {
				reasoning, s.pending = s.pending[:i], strings.TrimLeft(s.pending[i+len("</think>"):], "\r\n")
				s.state = 2
				content, s.pending = s.pending, ""
				return content, reasoning
			}
			// Keep a possible partial "</think>" back for the next chunk.
			keep := 0
			for k := len("</think>") - 1; k > 0; k-- {
				if strings.HasSuffix(s.pending, "</think>"[:k]) {
					keep = k
					break
				}
			}
			reasoning, s.pending = s.pending[:len(s.pending)-keep], s.pending[len(s.pending)-keep:]
			return "", reasoning
		case 2:
			content, s.pending = s.pending, ""
			return content, ""
		}
	}
}

func (s *thinkSplitter) flush() (content, reasoning string) {
	p := s.pending
	s.pending = ""
	if s.state == 1 {
		return "", p
	}
	return p, ""
}

// generate streams one reply from llama-server into g and the store, and
// returns how it ended.
func (cs *ChatService) generate(ctx context.Context, g *generation, inst *Instance, p chatParams) genDone {
	if inst.conf.role == roleImageGen {
		return cs.generateImage(ctx, g, inst, p)
	}
	t := g.t
	v := Variant{ID: t.VariantID, Status: variantStreaming}
	start := time.Now()
	var firstAt, reasonStart, reasonEnd time.Time
	var stats replyStats

	finish := func(status, errMsg string) genDone {
		g.mu.Lock()
		v.Content, v.Reasoning = g.content.String(), g.reasoning.String()
		g.mu.Unlock()
		v.Status, v.Error = status, errMsg
		if !reasonStart.IsZero() {
			end := reasonEnd
			if end.IsZero() {
				end = time.Now()
			}
			v.ReasoningMs = end.Sub(reasonStart).Milliseconds()
		}
		stats.TotalMs = time.Since(start).Milliseconds()
		if !firstAt.IsZero() {
			stats.TTFTMs = firstAt.Sub(start).Milliseconds()
		}
		v.Stats, _ = json.Marshal(stats)
		if err := cs.store.SaveVariant(v); err != nil {
			log.Printf("chat %s: saving reply: %v", t.ChatID, err)
		}
		return genDone{MessageID: t.MessageID, VariantID: t.VariantID, Status: status, Error: errMsg,
			Content: v.Content, Reasoning: v.Reasoning, ReasoningMs: v.ReasoningMs, Stats: v.Stats}
	}

	hist, err := cs.store.History(t.ChatID, t.Seq)
	if err != nil {
		return finish(variantError, "reading chat history: "+err.Error())
	}
	vision := true
	if (cs.reader != nil && hasImages(hist)) || hasDescribedImages(hist) {
		props, err := inst.FetchProps(ctx)
		vision = err == nil && props.Vision
		if !vision && cs.reader != nil {
			if err := cs.describeHistory(ctx, g, inst.conf.Name, hist); err != nil {
				if ctx.Err() != nil {
					return finish(variantStopped, "")
				}
				return finish(variantError, err.Error())
			}
		}
	}
	body := map[string]any{"messages": promptMessages(hist, p.System, vision), "stream": true, "cache_prompt": true}
	for k, val := range p.opts {
		body[k] = val
	}
	if !p.Think {
		body["chat_template_kwargs"] = map[string]any{"enable_thinking": false}
		body["reasoning_effort"] = "low"
	}
	data, _ := json.Marshal(body)
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, inst.baseURL()+"/v1/chat/completions", bytes.NewReader(data))
	if err != nil {
		return finish(variantError, err.Error())
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := chatClient.Do(req)
	if err != nil {
		if ctx.Err() != nil {
			return finish(variantStopped, "")
		}
		return finish(variantError, "couldn't reach "+inst.conf.Name+": "+err.Error())
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return finish(variantError, upstreamError(resp))
	}

	var split thinkSplitter
	emit := func(content, reasoning string) {
		if content == "" && reasoning == "" {
			return
		}
		now := time.Now()
		if firstAt.IsZero() {
			firstAt = now
		}
		g.mu.Lock()
		defer g.mu.Unlock()
		if reasoning != "" {
			if reasonStart.IsZero() {
				reasonStart = now
			}
			g.reasoning.WriteString(reasoning)
			g.publish(genEvent{"delta", map[string]string{"r": reasoning}})
		}
		if content != "" {
			if !reasonStart.IsZero() && reasonEnd.IsZero() {
				reasonEnd = now
			}
			g.content.WriteString(content)
			g.publish(genEvent{"delta", map[string]string{"c": content}})
		}
	}
	lastSave := time.Now()
	sc := bufio.NewScanner(resp.Body)
	sc.Buffer(make([]byte, 64<<10), 8<<20)
	for sc.Scan() {
		line := sc.Text()
		if !strings.HasPrefix(line, "data:") {
			continue
		}
		payload := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
		if payload == "" || payload == "[DONE]" {
			continue
		}
		var ch streamChunk
		if json.Unmarshal([]byte(payload), &ch) != nil {
			continue
		}
		if ch.Error != nil {
			c, r := split.flush()
			emit(c, r)
			return finish(variantError, ch.Error.Message)
		}
		for _, c := range ch.Choices {
			if c.Delta.ReasoningContent != "" {
				emit("", c.Delta.ReasoningContent)
			}
			if c.Delta.Content != "" {
				emit(split.feed(c.Delta.Content))
			}
			if c.FinishReason != "" {
				stats.Finish = c.FinishReason
			}
		}
		if ch.Timings != nil {
			stats.TPS, stats.Tokens = ch.Timings.PredictedPerSec, ch.Timings.PredictedN
			stats.PromptTok, stats.PromptTPS = ch.Timings.PromptN, ch.Timings.PromptPerSecond
		}
		if ch.Usage != nil && stats.Tokens == 0 {
			stats.Tokens, stats.PromptTok = ch.Usage.CompletionTokens, ch.Usage.PromptTokens
		}
		if time.Since(lastSave) >= saveEvery {
			lastSave = time.Now()
			g.mu.Lock()
			v.Content, v.Reasoning = g.content.String(), g.reasoning.String()
			g.mu.Unlock()
			if err := cs.store.SaveVariant(v); err != nil {
				log.Printf("chat %s: saving partial reply: %v", t.ChatID, err)
			}
		}
	}
	c, r := split.flush()
	emit(c, r)
	if ctx.Err() != nil {
		return finish(variantStopped, "")
	}
	if err := sc.Err(); err != nil {
		return finish(variantError, "reply cut off: "+err.Error())
	}
	return finish(variantDone, "")
}

// upstreamError extracts llama-server's error message from a failed response.
func upstreamError(resp *http.Response) string {
	b, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	var e struct {
		Error struct {
			Message string `json:"message"`
		} `json:"error"`
	}
	if json.Unmarshal(b, &e) == nil && e.Error.Message != "" {
		return e.Error.Message
	}
	msg := strings.TrimSpace(string(b))
	if msg == "" {
		msg = resp.Status
	}
	return truncateRunes(msg, 400)
}

// writeTitle asks the model for a short title once the first reply is done.
// It keeps a title the user already changed.
func (cs *ChatService) writeTitle(inst *Instance, chatID string) string {
	user, _, err := cs.store.FirstExchange(chatID)
	if err != nil || strings.TrimSpace(user) == "" {
		return ""
	}
	ctx, cancel := context.WithTimeout(cs.ctx, 30*time.Second)
	defer cancel()
	// Only the question: small models asked to title a whole exchange tend
	// to return the answer ("28GB") instead of the topic.
	prompt := "Name the topic of this request in 2 to 6 plain words, like an entry in a chat history list. " +
		"Reply with the title only: no quotes, no full stop, no answer to the request.\n\nRequest: " + truncateRunes(user, 1200)
	body, _ := json.Marshal(map[string]any{
		"messages":             []map[string]string{{"role": "user", "content": prompt}},
		"max_tokens":           48,
		"temperature":          0.3,
		"chat_template_kwargs": map[string]any{"enable_thinking": false},
		"reasoning_effort":     "low",
	})
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, inst.baseURL()+"/v1/chat/completions", bytes.NewReader(body))
	if err != nil {
		return ""
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := chatClient.Do(req)
	if err != nil {
		return ""
	}
	defer resp.Body.Close()
	var out struct {
		Choices []struct {
			Message struct {
				Content string `json:"content"`
			} `json:"message"`
		} `json:"choices"`
	}
	if resp.StatusCode != http.StatusOK || json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&out) != nil || len(out.Choices) == 0 {
		return ""
	}
	title := cleanTitle(out.Choices[0].Message.Content)
	if title == "" {
		return ""
	}
	c, err := cs.store.GetChat(chatID)
	if err != nil || (c.Title != autoTitle(user) && c.Title != defaultChatTitle) {
		return ""
	}
	if _, err := cs.store.UpdateChat(chatID, ChatPatch{Title: &title}); err != nil {
		return ""
	}
	return title
}

func cleanTitle(s string) string {
	if i := strings.Index(s, "</think>"); i >= 0 {
		s = s[i+len("</think>"):]
	}
	for _, line := range strings.Split(s, "\n") {
		line = strings.TrimSpace(line)
		line = strings.TrimLeft(line, "#*-> ")
		line = strings.TrimPrefix(line, "Title:")
		line = strings.Trim(strings.TrimSpace(line), `"'“”‘’*_.`)
		if line == "" {
			continue
		}
		if !strings.Contains(line, " ") && strings.Count(line, "_") >= 1 {
			line = strings.ReplaceAll(line, "_", " ")
		}
		if n := len(strings.Fields(line)); n < 2 || n > 10 {
			return ""
		}
		return truncateRunes(line, 60)
	}
	return ""
}
